import gc
import sys

def listener_count(emitter):
    return sum(len(lst) for lst in emitter._listeners.values())

def memory_leak_demo():
    emitter = EventEmitter()
    # Warm‑up
    for _ in range(1000):
        process_batch(emitter, [1, 2, 3])
    # Force a garbage collection pass
    gc.collect()
    # Record listener count after many calls
    count_before = listener_count(emitter)
    print(f"Listeners after many calls (should be 0): {count_before}")
    # Verify that no listeners remain
    assert count_before == 0, "Listener leak detected"

if __name__ == "__main__":
    memory_leak_demo()
